// deleteSupersededCredentials removes the access, refresh, and jurisdiction
// credentials of every legacy login the single-login model can no longer reach.
// current — which may be nil, meaning nothing survives — is left alone, as are
// the jurisdiction tokens it shares by handle.
func deleteSupersededCredentials(legacy *File, current *Context) {
	var currentName, currentHandle string
	currentAudiences := map[string]bool{}
	if current != nil {
		currentName, currentHandle = current.Name, current.Handle
		for _, audience := range current.JurisdictionAudiences {
			currentAudiences[audience] = true
		}
	}
	for _, old := range legacy.Contexts {
		if old == nil || old.Handle == "" || (current != nil && old.Name == currentName) {
			continue
		}
		if old.KeychainService != "" {
			_ = tokenstore.Delete(tokenstore.RefreshService(old.KeychainService), old.Handle) //nolint:errcheck // best-effort migration cleanup
			_ = tokenstore.Delete(old.KeychainService, old.Handle)                            //nolint:errcheck // best-effort migration cleanup
