			if audience == "" || (old.Handle == currentHandle && currentAudiences[audience]) {
				continue
			}
			_ = tokenstore.Delete(tokenstore.JurisdictionService(audience), old.Handle) //nolint:errcheck // best-effort migration cleanup
		}
	}
