// selectContext resolves the login context for a resource from the ACTIVE
// context alone. subject is a noun phrase identifying the resource ("cluster
// nyc.entire.io" / "API host partial.to") used in messages, so the same rule
// serves both the git-cluster and data-API resolvers.
//
// `entire auth use <name>` is the only thing that decides which identity acts;
// the resource's advertised issuers decide only whether that identity is
// accepted. There is deliberately no implicit selection — see
// ResolveContextForCluster for why the earlier fallback tiers were removed.
//
// Anything else is an error, and which error depends on what the user can
// actually do about it (unusableActiveContextError): switch to a stored login
// that this resource does trust, or obtain one.
func selectContext(f *contexts.File, subject string, coreURLs []string, debugf DebugFunc) (*contexts.Context, error) {
	current := f.Find(f.CurrentContext)
	if current != nil && contextEligible(current, coreURLs) {
		debugf("%s -> active context %s", subject, current.Name)
		return current, nil
	}
	if current != nil {
		debugf("%s -> active context %s (%s) is not trusted here", subject, current.Name, current.CoreURL)
	}
	return nil, unusableActiveContextError(subject, current, eligibleContexts(f, coreURLs), coreURLs)
}

// contextEligible reports whether c's core is among the resource's advertised
// trusted issuers, compared trailing-slash-insensitively to match how core URLs
// are compared everywhere else (contexts.ContextsForIssuer, auth.sameIssuer).
// A context with no CoreURL is never eligible: it names no issuer to match.
func contextEligible(c *contexts.Context, coreURLs []string) bool {
	want := strings.TrimRight(c.CoreURL, "/")
	if want == "" {
		return false
	}
	return slices.ContainsFunc(coreURLs, func(coreURL string) bool {
		return strings.TrimRight(coreURL, "/") == want
	})
}

// eligibleContexts returns the local contexts whose core is among coreURLs,
// de-duplicated by name. Only ever reported to the user — never used to pick a
// context, so no element of it is a silent winner.
func eligibleContexts(f *contexts.File, coreURLs []string) []*contexts.Context {
	seen := make(map[string]bool)
	var out []*contexts.Context
	for _, coreURL := range coreURLs {
		for _, c := range f.ContextsForIssuer(coreURL) {
			if !seen[c.Name] {
				seen[c.Name] = true
				out = append(out, c)
			}
		}
	}
	return out
}

// unusableActiveContextError explains why no identity is available for the
// resource, distinguishing the states the user can be in — because the remedy
// differs and a wrong remedy is a dead end. When a stored login would work, the
// fix is local (`auth use`) and the message names the candidates; when none
// would, the user needs a new login against a server the resource trusts, so
// renderLoginHint names those servers.
//
// Reporting "not logged in" for a user who IS logged in — just to a federation
// this resource doesn't trust — sends them to `entire login`, which
// re-authenticates against the default server and reproduces the same failure.
// Naming the active login is what makes the mismatch legible.
func unusableActiveContextError(subject string, current *contexts.Context, eligible []*contexts.Context, coreURLs []string) error {
	if len(eligible) > 0 {
		return fmt.Errorf("%s does not accept your active login%s.\nThese saved logins can authenticate it: %s\nSwitch with `entire auth use <context>`, then re-run your command.",
			subject, describeActiveContext(current), strings.Join(contextNames(eligible), ", "))
	}
	if current != nil {
		return fmt.Errorf("%s does not accept your active login%s, and no other saved login does either.\n%s",
			subject, describeActiveContext(current), renderLoginHint(subject, coreURLs))
	}
	return errors.New(renderLoginHint(subject, coreURLs))
}

// describeActiveContext renders the " <name> (<core>)" clause naming the active
// login, or "" when there is none — so one message template covers both the
// wrong-federation and no-active-context cases without an empty `""` or a
// dangling paren.
func describeActiveContext(current *contexts.Context) string {
	if current == nil {
		return ""
	}
	if core := strings.TrimRight(current.CoreURL, "/"); core != "" {
		return fmt.Sprintf(" %q (%s)", current.Name, core)
	}
	return fmt.Sprintf(" %q", current.Name)
}

// contextNames returns the contexts' names, sorted so error messages are stable
// across saves and across runs.
func contextNames(cs []*contexts.Context) []string {
	names := make([]string, len(cs))
	for i, c := range cs {
		names[i] = c.Name
	}
	slices.Sort(names)
	return names
}

