func contextEligible(c *contexts.Context, coreURLs []string) bool {
	want := strings.TrimRight(c.CoreURL, "/")
	if want == "" {
		return false
	}
	return slices.ContainsFunc(coreURLs, func(coreURL string) bool {
		return strings.TrimRight(coreURL, "/") == want
